import {candidateEvidence,eligiblePortrait,coverageAudit,rosterEvidence} from './profile-evidence.js';
import {verifiedProbability} from './election-visual.js';
const partyNames={D:'民主党',R:'共和党',I:'独立',L:'自由意志党',G:'绿党'};
const placeholder='<svg viewBox="0 0 80 90" aria-hidden="true"><circle cx="40" cy="28" r="13"/><path d="M16 78v-9c0-28 48-28 48 0v9"/></svg><small>非真人占位图</small>';
const link=(url,text,esc)=>url?`<a href="${esc(url)}" target="_blank" rel="noopener">${esc(text)} ↗</a>`:'';
const items=(list,esc)=>(list||[]).map(x=>`<li>${esc(x.text||x.title||x)} ${x.attribution?`<small>${esc(x.attribution)}</small>`:''} ${link(x.source,'来源',esc)}</li>`).join('');
const record=(title,list,esc)=>`<section class="profile-evidence-block"><h4>${esc(title)}</h4>${list?.length?`<ul>${items(list,esc)}</ul>`:'<p class="missing-evidence">未取得可核验证据，不代表不存在。</p>'}</section>`;
function portrait(person,esc){const photo=eligiblePortrait(person);return `<div class="profile-image">${photo?`<img src="${esc(photo.url)}" alt="${esc(person.name)}" loading="lazy" referrerpolicy="no-referrer">`:placeholder}</div>${photo?`<p class="portrait-credit">${esc(photo.credit||photo.attribution||photo.license||'')} · ${link(photo.source,'图片来源',esc)} · ${link(photo.rightsSource,'使用依据',esc)}</p>`:'<p class="portrait-credit">身份或图片使用依据待核验。</p>'}`;}
export function profileHTML(seat,profile,esc,label){
 const p=profile||{},inc=p.incumbent||{},probability=verifiedProbability(seat),roster=rosterEvidence(p);
 const current=`<section class="incumbent-record"><p class="eyebrow">CURRENT OFFICEHOLDER</p><div class="candidate-heading"><div>${portrait({...inc,name:inc.name||seat.incumbent},esc)}</div><div><h2>${esc(inc.name||seat.incumbent||'现任空缺')}</h2><span class="profile-badge">现任 · ${esc(partyNames[seat.currentParty]||'空缺')}</span><p>${esc(inc.role||'')}</p></div></div><p>${esc(inc.background||'履历待核验')}</p>${link(inc.backgroundSource||inc.source||seat.source,'现任资料来源',esc)}${record('政策主张',inc.policyPositions?.length?inc.policyPositions:inc.positions,esc)}${record('成果与立法工作',inc.majorAchievements?.length?inc.majorAchievements:inc.achievements||inc.accomplishments,esc)}${record('荣誉记录',inc.honors,esc)}</section>`;
 const candidates=(p.candidates||[]).map(c=>{const e=candidateEvidence(c);return `<article class="candidate-card party-${esc(c.party)}"><p class="eyebrow">2026 CANDIDATE RECORD</p><div class="candidate-heading"><div>${portrait(c,esc)}</div><div><h3>${esc(c.name)}</h3><span class="profile-badge">${esc(partyNames[c.party]||c.party||'党籍待核验')}</span><p class="verification-label">${e.officiallyConfirmed?'来源标记为官方确认':'公开候选名录记录；不代表完整官方选票'}</p></div></div><p>${link(e.source,'参选依据',esc)} · 资料时间 ${esc(c.asOf||c.verifiedAt||p.profileAsOf||'待核验')}</p>${e.biography?`<p>${esc(c.background)}</p>${link(e.biographySource,'履历依据',esc)}`:'<p class="missing-evidence">履历尚待核验，不以现任身份或党派补写。</p>'}${record('政策主张',e.policy,esc)}${record('成果与立法工作',e.achievements,esc)}${record('荣誉记录',e.honors,esc)}<p class="gap-list">待补证据：${e.gaps.length?e.gaps.map(esc).join(' · '):'已记录各类来源；仍需持续复核'}</p>${(c.polls||[]).map(q=>`<div class="candidate-poll"><strong>${q.share==null?'—':esc(q.share)+'%'}</strong><div>${esc(q.pollster)} · 原始民调<br>${esc(q.fieldStart)}—${esc(q.fieldEnd)} · ${esc(q.sampleType||'样本见来源')}<br>${link(q.source,'调查原文',esc)}</div></div><details class="poll-method"><summary>调查方法与限制</summary><p>${esc(q.note||'')}</p><p>样本：${esc(q.sample||'见来源')}；模式：${esc(q.mode||'见来源')}；权重：${esc(q.weighting||'见来源')}；误差：${q.moe==null?'见来源':'±'+esc(q.moe)+'个百分点'}</p></details>`).join('')}</article>`;}).join('');
 return `<p class="eyebrow">${esc(label(seat))} / ${seat.contested2026?'2026竞选席位':'不改选席位'}</p><p class="profile-separation">现任与2026候选人分别核验。当前任职不等于已获提名，也不证明将再次参选。</p>${current}${seat.contested2026?`<div class="divider"></div><h2>2026 候选记录</h2><p class="coverage-alert">${roster.verified?'官方印刷选票名单已核验；未单列的写入候选人仍可能未覆盖。':'名单尚未证明完整；其他党派、独立或写入候选人可能未覆盖。'} ${link(roster.source,'参选依据',esc)}</p>${candidates||'<p class="missing-evidence">此席暂无可展示的已核验候选记录。</p>'}<div class="forecast-note">${probability?`<strong>来源模型胜选概率</strong><p>${Object.entries(probability.values).filter(([,v])=>v>0).map(([side,v])=>esc(partyNames[side]||side)+' '+esc(Math.round(v*1000)/10)+'%').join(' · ')}</p><p>${esc(probability.model)} · ${esc(probability.asOf)} · ${link(probability.source,'模型来源',esc)}</p>`:'<strong>没有可核验的逐席胜选概率模型；不把民调或定性评级换算为百分比。</strong>'}</div>`:''}<p class="small muted">资料截至 ${esc(p.profileAsOf||'待核验')}<br>${esc(p.note||'')}</p>`;
}
export function coverageHTML(seats,profiles,chamber,esc){const a=coverageAudit(seats,profiles,chamber);return `<div class="coverage-heading"><div><span class="eyebrow">CANDIDATES & EVIDENCE</span><h3>候选资料覆盖审计</h3></div><button id="download-profile-audit">下载缺失清单</button></div><div class="coverage-grid"><div><b>${a.seatsWithCandidates} / ${a.contestedSeats}</b><span>改选席已有候选记录</span></div><div><b>${a.candidateRecords}</b><span>候选人记录数</span></div><div><b>${a.completeRosters} / ${a.contestedSeats}</b><span>官方印刷选票名单已核验</span></div><div><b>${a.portraits} / ${a.candidateRecords}</b><span>身份与使用依据齐备头像</span></div></div><p class="small">已附来源：履历 ${a.biographies} · 政策 ${a.policies} · 成果 ${a.achievements} · 荣誉 ${a.honors}</p><p class="small muted">有记录不等于名单完整，有来源不等于独立验证所有主张。缺失表示尚未核验，不表示没有资历或成就。</p>`;}
export function installImageFallbacks(panel){for(const image of panel.querySelectorAll('.profile-image img'))image.onerror=()=>{image.parentElement.innerHTML=placeholder;};}
